SELECT s.browser, s.customer_id, t.avg_duration_sec, t.event_type_values FROM sessions s LEFT JOIN (SELECT session_id, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) AS event_type_values FROM web_events GROUP BY session_id) t ON s.id = t.session_id ORDER BY avg_duration_sec
